public static void main(String[] args) {
  Scanner sc = new Scanner(System.in);
  String S = sc.next();
  int[] count = new int[26];
  for (int i = 0; i < S.length(); i++) {
      count[S.charAt(i) - 'a']++;
  }
  char uniqueChar = ' ';
  for (int i = 0; i < 26; i++) {
      if (count[i] == 1) {
          uniqueChar = (char) (i + 'a');
          break;
      }
  }
  for (int i = 0; i < S.length(); i++) {
      if (S.charAt(i) == uniqueChar) {
          System.out.println(i + 1);
          return;
      }
